import unittest
from cli import run

class Tests(unittest.TestCase):
    def test_old(self):
        self.assertEqual(run(["count","[1,2]"]),(0,"2\n",""))

    def test_show_baseline(self):
        self.assertEqual(run(["show", '["a", "b"]']), (0, "a, b\n", ""))

    def test_show_upper(self):
        self.assertEqual(run(["show", "--upper", '["a", "b"]']), (0, "A, B\n", ""))

    def test_count_upper_rejected(self):
        self.assertEqual(run(["count", "--upper", '["a", "b"]']), (2, "", "usage\n"))

    def test_show_errors_preserved(self):
        self.assertEqual(run(["show", "--upper", "invalid"]), (2, "", "invalid json\n"))
        self.assertEqual(run(["show", "--upper", "123"]), (2, "", "expected list\n"))
        self.assertEqual(run(["show"]), (2, "", "usage\n"))
